efense_mult":1}],"seat_player_ids":[-1,-2,-3,1]}$json$::jsonb;
begin
  insert into auth.users (id, aud, role, email) values (u1, 'authenticated', 'authenticated', u1 || '@t.test');
  insert into public.games (name, created_by, max_players, status, tick_speed, fill_with_ai, ai_difficulty, map_size, starting_territories, victory_pct)
  values ('councilsuite', u1, 4, 'lobby', 'fast', true, 4, 'compact', 3, 1.0) returning id into g;
  insert into public.game_players (game_id, user_id, faction_slug, display_name) values (g, u1, 'kaldran', 'One') returning id into p1;
  lay := jsonb_set(lay, '{seat_player_ids}', (select jsonb_agg(case when (e #>> '{}')::int = 1 then to_jsonb(p1) else e end) from jsonb_array_elements(lay -> 'seat_player_ids') e));
  perform public.start_game(g, lay);
  select current_tick into tk from public.games where id = g;
  select id into t1 from public.game_territories where game_id = g and owner_player_id = p1 order by id limit 1;
  update public.game_players set gold = 1000 where id = p1;

  select count(*) into n from public.council_members where game_id = g and status = 'seated';
  if n = 28 then ok := ok + 1; else bad := bad + 1; res := res || 'seven seated councillors per player (got ' || n || '); '; end if;

  update public.realm_areas set level = 3 where player_id = p1 and area = 'armory';
  perform set_config('request.jwt.claims', jsonb_build_object('sub', u1, 'role', 'authenticated')::text, true);
  set local role authenticated;
  c := (public.deploy_councillor(g, 'armory', t1) ->> 'commander_id')::int;
  reset role;
  select level, banked_level into v1, v2 from public.realm_areas where player_id = p1 and area = 'armory';
  if v1 = 1 and v2 = 3 and public.armory_level(p1) = 1 and (select council_area = 'armory' from public.commanders where id = c) and (select status from public.council_members where player_id = p1 and area = 'armory') = 'afield' then ok := ok + 1; else bad := bad + 1; res := res || 'deploy suppresses the seat bonus (' || v1 || '/' || coalesce(v2, -1) || '); '; end if;

  set local role authenticated;
  begin perform public.deploy_councillor(g, 'armory', t1); st := 'allowed'; exception when others then st := sqlerrm; end;
  reset role;
  if st like '%already in the field%' then ok := ok + 1; else bad := bad + 1; res := res || 'cannot deploy twice (got ' || st || '); '; end if;

  update public.commanders set troops = 7 where id = c;
  select troops into tr from public.game_territories where id = t1;
  set local role authenticated;
  perform public.recall_councillor(g, c);
  reset role;
  if (select level from public.realm_areas where player_id = p1 and area = 'armory') = 3 and (select status from public.council_members where player_id = p1 and area = 'armory') = 'seated' and (select troops from public.game_territories where id = t1) = tr + 7 and (select status from public.commanders where id = c) = 'dead' then ok := ok + 1; else bad := bad + 1; res := res || 'recall restores the seat and returns troops; '; end if;

  set local role authenticated;
  c := (public.deploy_councillor(g, 'armory', t1) ->> 'commander_id')::int;
  reset role;
  perform public.kill_commanders(g, array[c], tk);
  if (select status from public.council_members where player_id = p1 and area = 'armory' and status = 'dead' limit 1) = 'dead' and not exists (select 1 from public.council_members where player_id = p1 and area = 'armory' and status <> 'dead') then ok := ok + 1; else bad := bad + 1; res := res || 'death vacates the seat; '; end if;
  if (select morale_until_tick from public.game_players where id = p1) = tk + 24 and (select level from public.realm_areas where player_id = p1 and area = 'armory') = 1 then ok := ok + 1; else bad := bad + 1; res := res || 'councillor death costs morale and the seat stays suppressed; '; end if;

  set local role authenticated;
  perform public.recruit_councillor(g, 'armory');
  reset role;
  if (select level from public.realm_areas where player_id = p1 and area = 'armory') = 3 and (select gold from public.game_players where id = p1) = 850 and exists (select 1 from public.council_members where player_id = p1 and area = 'armory' and status = 'seated') then ok := ok + 1; else bad := bad + 1; res := res || 'recruiting restores the seat for 150 gold; '; end if;

  set local role authenticated;
  begin perform public.recruit_councillor(g, 'armory'); st := 'allowed'; exception when others then st := sqlerrm; end;
  reset role;
  if st like '%not vacant%' then ok := ok + 1; else bad := bad + 1; res := res || 'cannot recruit into a filled seat; '; end if;

  for i in 1..40 loop perform public.run_tick(g); end loop;
  select count(*) into n from public.game_events where game_id = g and type = 'ai_error';
  if n = 0 then ok := ok + 1; else bad := bad + 1; res := res || 'AI ran 40 ticks with ' || n || ' errors; '; end if;

  set local role anon;
  begin perform public.deploy_councillor(g, 'armory', t1); st := 'allowed'; exception when insufficient_privilege then st := 'denied'; end;
  reset role;
  if st = 'denied' then ok := ok + 1; else bad := bad + 1; res := res || 'anon cannot deploy; '; end if;

  raise exception 'COUNCIL passed=% failed=% %', ok, bad, res;
end $$;
